INSERT INTO `coa_client_spell_description` (`ID`, `Description`, `ToolTip`) VALUES
(500217, 'The target becomes blighted, causing nearby enemies to suffer ${($d*1000/$t1)*($m1+0+$SP*0.169175)} Shadow damage over $d, plus ${$m1+0+$SP*0.169175} Shadow damage when cast.\r\n\r\nAfter $d, the blight expunges from the target dealing $500459s2 Nature damage.', ''),
(500335, 'Raise an |cffffffffAbomination|r to aid you in combat, occupying 3 |cffffffffLife Force|r.\r\n\r\nIt is surrounded by a disease cloud, dealing ${$802353m1+$802353ppl1+$SP*0.25} Nature damage to nearby enemies when it takes damage.\r\n\r\n|cff90ee90Command|r: Instantly unleashes an empowered disease cloud around it.', ''),
(500365, 'Raise an |cffffffffAbomination|r to aid you in combat, occupying 3 |cffffffffLife Force|r.\r\n\r\nIt is surrounded by a disease cloud, dealing ${$802353m1+$802353ppl1+$SP*0.25} Nature damage to nearby enemies when it takes damage.\r\n\r\n|cff90ee90Command|r: Instantly unleashes an empowered disease cloud around it.', ''),
(500456, 'The target becomes blighted, causing nearby enemies to suffer ${($d*1000/$t1)*($m1+0+$SP*0.169175)} Shadow damage over $d, plus ${$m1+0+$SP*0.169175} Shadow damage when cast.\r\n\r\nAfter $d, the blight expunges from the target dealing $500459s2 Nature damage.', ''),
(500457, 'The target becomes blighted, causing nearby enemies to suffer ${($d*1000/$t1)*($m1+0+$SP*0.169175)} Shadow damage over $d, plus ${$m1+0+$SP*0.169175} Shadow damage when cast.\r\n\r\nAfter $d, the blight expunges from the target dealing $500459s2 Nature damage.', ''),
(500458, 'The target becomes blighted, causing nearby enemies to suffer ${($d*1000/$t1)*($m1+0+$SP*0.169175)} Shadow damage over $d, plus ${$m1+0+$SP*0.169175} Shadow damage when cast.\r\n\r\nAfter $d, the blight expunges from the target dealing $500459s2 Nature damage.', ''),
(500459, 'The target becomes blighted, causing nearby enemies to suffer ${($d*1000/$t1)*($m1+0+$SP*0.169175)} Shadow damage over $d, plus ${$m1+0+$SP*0.169175} Shadow damage when cast.\r\n\r\nAfter $d, the blight expunges from the target dealing $500459s2 Nature damage.', ''),
(500971, 'Raise a |cffffffffGhoul|r to aid you in combat occupying 1 |cffffffffLife Force|r. \r\n\r\nIts auto attacks restore ${($707000m1+$707000ppl1+(($INT*0.504)+($SP*0.504))*0.07)*0.7} health to you.\r\n\r\n|cff90ee90Command|r: Expels leeching plague that strikes up to $801514i nearby enemies, dealing ${(($INT*0.28+$SP*0.28)*0.2+($INT*0.504+$SP*0.504)*0.2)+$801514m1} Plague damage, and healing you for ${($801514m3+$801514ppl3+$SP*0.22+$INT*.50)*0.7} for each |cffffffffGhoul|r.', ''),
(504021, 'Command your |cffffffffGhouls|r to expel plague, leeching enemies within $801514a1 yds for ${$801514m1+$801514ppl1+$SP*0.375+$INT*.5} Plague damage, and healing you for ${($801514m3+$801514ppl3+$SP*0.22+$INT*.50)*0.7} for each |cffffffffGhoul|r.\r\n\r\n@ext:Not usable while in |cFFFFFFFFUndead: Pacify|r.:ext@', ''),
(561138, 'Chant a powerful ritual that brings forth $561316s1 |cffffffffRotting Frost Giant|r near you to aid you in combat for $561316d and generate $/10;561317s1 Runic Power, repeating every $t1 sec for $d.\r\n\r\nFor the duration, your Undead minions are guaranteed to critically strike. Blocked, missed, dodged and parried hits do not critically strike.', ''),
(704355, '|cff3399ffRequires Frozen Target|r\r\nCall down icy boulders onto a |cff3399ffFrozen|r enemy, dealing ${$m1+0+$spfr*1.405} Frost damage.$?s560852[\r\n\r\nThis spell is guaranteed to critically strike.][]\r\n\r\n@ext:Damage increased by your Frost spell critical strike chance. :ext@', ''),
(705750, 'Dealing Magic damage now has a $h% chance to increase your haste by $705751s1% for $705751d.', ''),
(707007, 'Beckon the restless dead to rise and march forward.\r\n\r\nWhen they reach an enemy they explode, dealing ${$707010m1*$<scalingbp>+$SP*.75} Plague damage (Nature or Shadow spell power) to nearby enemies and slowing their movement speed by $707010s2% for $707010d.', ''),
(707283, 'Critical strikes dealt by your |cffffffffAbominations|r and |cffffffffDecaying Collosi|r now |cFFFFFFFFChomp|r your target, dealing ${$707284m1+($SP*2.25)*0.5} damage to them, increased with your level.', ''),
(707399, '|cff3399ffRequires Frozen Target|r\r\nCall down icy boulders onto a |cff3399ffFrozen|r enemy, dealing ${$m1+0+$spfr*1.405} Frost damage.$?s560852[\r\n\r\nThis spell is guaranteed to critically strike.][]\r\n\r\n@ext:Damage increased by your Frost spell critical strike chance. :ext@', ''),
(707400, '|cff3399ffRequires Frozen Target|r\r\nCall down icy boulders onto a |cff3399ffFrozen|r enemy, dealing ${$m1+0+$spfr*1.405} Frost damage.$?s560852[\r\n\r\nThis spell is guaranteed to critically strike.][]\r\n\r\n@ext:Damage increased by your Frost spell critical strike chance. :ext@', ''),
(707401, '|cff3399ffRequires Frozen Target|r\r\nCall down icy boulders onto a |cff3399ffFrozen|r enemy, dealing ${$m1+0+$spfr*1.405} Frost damage.$?s560852[\r\n\r\nThis spell is guaranteed to critically strike.][]\r\n\r\n@ext:Damage increased by your Frost spell critical strike chance. :ext@', ''),
(707402, '|cff3399ffRequires Frozen Target|r\r\nCall down icy boulders onto a |cff3399ffFrozen|r enemy, dealing ${$m1+0+$spfr*1.405} Frost damage.$?s560852[\r\n\r\nThis spell is guaranteed to critically strike.][]\r\n\r\n@ext:Damage increased by your Frost spell critical strike chance. :ext@', ''),
(707911, '|cff3399ffRequires Frozen Target|r\r\nCall down icy boulders onto a |cff3399ffFrozen|r enemy, dealing ${$m1+0+$spfr*1.405} Frost damage.$?s560852[\r\n\r\nThis spell is guaranteed to critically strike.][]\r\n\r\n@ext:Damage increased by your Frost spell critical strike chance. :ext@', ''),
(712434, 'Increases the damage of your |cFFFFFFFFGlacial Impact|r by $s1% for $d, stacking $u times.\r\n\r\nReaching 10 stacks causes your |cFFFFFFFFGlacial Impact|r to critically strike for 50% increased damage.', ''),
(801724, 'Launch a chain of frost at an enemy, dealing ${$801728m1+$801728ppl1+$spfr*0.35} Frost Damage every $t1 sec for $d.\r\n\r\nEach tick generates 3 to 8 Runic Power.', ''),
(803768, 'Create $s1 |cffffffffBone Reliquaries|r that restores $803767s1% of your missing health.\r\n\r\nAllies may only use a |cffffffffBone Reliquary|r once per minute, and once per combat: the minute starts when combat ends. Shares a cooldown with similar effects.', ''),
